      printUsage();
      process.exit(1);
    } else {
      inputFile = arg;
    }
  }

  if (!inputFile) {
    console.error("Error: No input file specified");
    printUsage();
    process.exit(1);
  }

  return { inputFile, outputFile, includeImages };
}

async function main(): Promise<void> {
  const { inputFile, outputFile, includeImages } = parseArgs(process.argv);

  const absolutePath = path.resolve(inputFile);
  if (!fs.existsSync(absolutePath)) {
    console.error(`Error: File not found: ${absolutePath}`);
    process.exit(1);
  }

  const ext = path.extname(absolutePath).toLowerCase();
  const isImage = IMAGE_EXTENSIONS.has(ext);

  console.error(`Processing: ${path.basename(absolutePath)}`);

  const result = isImage
    ? await convertImageToMarkdown(absolutePath, {
        includeImageBase64: includeImages,
      })
    : await convertPdfToMarkdown(absolutePath, {
        includeImageBase64: includeImages,
      });

  console.error(`Done: ${result.pages.length} page(s) processed`);

  if (outputFile) {
    const outputPath = path.resolve(outputFile);
    fs.writeFileSync(outputPath, result.markdown, "utf-8");
    console.error(`Written to: ${outputPath}`);
  } else {
    process.stdout.write(result.markdown);
  }
}

main().catch((err) => {
  console.error("Error:", err.message ?? err);
  process.exit(1);
});

# pdf2md — Extracted Core

PDF/画像からMarkdownへの変換コア機能。Mistral OCR APIを直接利用し、S3依存なし。

## 必要条件

- Node.js 18+
- `MISTRAL_API_KEY` 環境変数

## セットアップ

```bash
# プロジェクトルートで依存関係をインストール（@mistralai/mistralai が必要）
npm install
```

## CLI使用方法

```bash
# stdoutにMarkdown出力
npx tsx extracted/cli.ts input.pdf

# ファイルに書き出し
npx tsx extracted/cli.ts input.pdf -o output.md

# 画像抽出なし
npx tsx extracted/cli.ts input.pdf -o output.md --no-images

# 画像ファイルも対応
npx tsx extracted/cli.ts photo.png -o output.md
```

## ライブラリとして使用

```typescript
import { convertPdfToMarkdown, convertImageToMarkdown } from "./extracted/pdf2md.js";

// PDF変換
const result = await convertPdfToMarkdown("document.pdf");
console.log(result.markdown);
console.log(`${result.pages.length} pages`);

// 画像変換
const imgResult = await convertImageToMarkdown("photo.png", {
  includeImageBase64: false,
});

// APIキーを直接渡す
const result2 = await convertPdfToMarkdown("document.pdf", {
  apiKey: "your-api-key",
});
```

## API

### `convertPdfToMarkdown(pdfPath, options?)`

PDFファイルをMarkdownに変換。

- `pdfPath` — PDFファイルのパス
- `options.includeImageBase64` — 画像Base64データを含めるか（デフォルト: `true`）
- `options.apiKey` — Mistral APIキー（デフォルト: `MISTRAL_API_KEY`環境変数）

### `convertImageToMarkdown(imagePath, options?)`

画像ファイルをMarkdownに変換。対応形式: PNG, JPG, GIF, WebP, BMP, TIFF

### 戻り値: `ConvertResult`

```typescript
{
  pages: Array<{
    index: number;
    markdown: string;
    images: Array<{ id: string; imageBase64?: string }>;
  }>;
  markdown: string; // 全ページ結合
}
```

## 設計判断

- **S3不要**: Mistral OCR APIはBase64データURLを直接受け取れるため、S3を経由する必要がない
- **環境変数1つ**: `MISTRAL_API_KEY`のみ必要（元アプリはAWS認証情報も必要だった）
- **外部依存最小**: `@mistralai/mistralai`のみ。CLIの引数パースも`process.argv`で直接処理

